import{_ as o,C as n,c as r,o as s,a3 as a,G as i}from"./chunks/framework.Dokpd4od.js";const v=JSON.parse('{"title":"Accounting Overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/get-started/accounting-overview.md","filePath":"master/finance/get-started/accounting-overview.md","lastUpdated":1792041590000}'),l={name:"master/finance/get-started/accounting-overview.md"};function h(c,e,u,d,g,p){const t=n("ImagePopup");return s(),r("div",null,[e[0]||(e[0]=a('<h1 id="accounting-overview" tabindex="-1">Accounting Overview <a class="header-anchor" href="#accounting-overview" aria-label="Permalink to &quot;Accounting Overview&quot;">​</a></h1><p>The Overview is the home page of the <strong>Accounting</strong> app. It shows one card for each journal, so you can see at a glance what waits for you: invoices to validate, bills to pay and the money moving through your bank. Each card also has a <strong>New</strong> button to start a new document in that journal.</p><blockquote><p><strong>In simple words:</strong> The Overview is your finance dashboard. Look at the cards, click a number to see the documents behind it, click <strong>New</strong> to add one.</p></blockquote><h2 id="open-the-overview" tabindex="-1">Open the Overview <a class="header-anchor" href="#open-the-overview" aria-label="Permalink to &quot;Open the Overview&quot;">​</a></h2><p>Go to <code>Accounting → Overview</code>. This page exists only in the <strong>Accounting</strong> app.</p>',5)),i(t,{src:"/images1/finance/accounting_overview.png",alt:"Accounting → Overview on the All tab, showing the Customer Invoices, Vendor Bills, Bank Transactions and Cash Transactions cards"}),e[1]||(e[1]=a('<h2 id="the-tabs" tabindex="-1">The tabs <a class="header-anchor" href="#the-tabs" aria-label="Permalink to &quot;The tabs&quot;">​</a></h2><p>The tabs at the top filter the cards by journal type.</p><ul><li><strong>All:</strong> every journal.</li><li><strong>Sales:</strong> journals of type Sale, such as Customer Invoices.</li><li><strong>Purchases:</strong> journals of type Purchase, such as Vendor Bills.</li><li><strong>Bank:</strong> bank journals.</li><li><strong>Cash:</strong> cash journals.</li><li><strong>Miscellaneous:</strong> general journals, such as Miscellaneous Operations.</li></ul><p>Only journals that are shown on the dashboard get a card. The default journals are all shown.</p><h2 id="read-a-journal-card" tabindex="-1">Read a journal card <a class="header-anchor" href="#read-a-journal-card" aria-label="Permalink to &quot;Read a journal card&quot;">​</a></h2><p>The card title is the journal name. Click it to open the list of documents for that journal. The card type decides what the numbers mean.</p><h3 id="sale-journals-customer-invoices" tabindex="-1">Sale journals (Customer Invoices) <a class="header-anchor" href="#sale-journals-customer-invoices" aria-label="Permalink to &quot;Sale journals (Customer Invoices)&quot;">​</a></h3><ul><li><strong>To Validate:</strong> the number of draft invoices and their total. Click it to open the <strong>Draft</strong> view.</li><li><strong>Unpaid:</strong> posted invoices that still have an amount due and are not yet paid or in payment. The amount is the total still due.</li><li><strong>Late:</strong> posted invoices that are not paid and past their due date. This line shows only when there are late invoices.</li><li><strong>To Pay:</strong> posted invoices that are <strong>Not paid</strong> or <strong>Partial</strong>, with the amount still due.</li></ul><h3 id="purchase-journals-vendor-bills" tabindex="-1">Purchase journals (Vendor Bills) <a class="header-anchor" href="#purchase-journals-vendor-bills" aria-label="Permalink to &quot;Purchase journals (Vendor Bills)&quot;">​</a></h3><p>The card shows <strong>To Validate</strong>, <strong>Late</strong> and <strong>To Pay</strong>. They work like the sale card, for bills.</p><h3 id="bank-and-cash-journals" tabindex="-1">Bank and cash journals <a class="header-anchor" href="#bank-and-cash-journals" aria-label="Permalink to &quot;Bank and cash journals&quot;">​</a></h3><p>The card shows <strong>Payments</strong>: the total of all posted entries in the journal. The chart is a line of the running balance over the last weeks.</p><h3 id="miscellaneous-journals" tabindex="-1">Miscellaneous journals <a class="header-anchor" href="#miscellaneous-journals" aria-label="Permalink to &quot;Miscellaneous journals&quot;">​</a></h3><p>The card shows <strong>Entries</strong>, the number of entries in the journal.</p><p>A line with no count and no amount stays hidden. A new company therefore shows empty cards.</p><h2 id="the-chart" tabindex="-1">The chart <a class="header-anchor" href="#the-chart" aria-label="Permalink to &quot;The chart&quot;">​</a></h2><p>Sale and purchase cards show a bar chart of the amounts still due, grouped by due date: <strong>Overdue</strong>, the previous week, <strong>This Week</strong>, the next two weeks and <strong>Not Due</strong>. Red bars are late amounts. Green bars are amounts that are not late yet.</p><h2 id="the-new-button" tabindex="-1">The New button <a class="header-anchor" href="#the-new-button" aria-label="Permalink to &quot;The New button&quot;">​</a></h2><p><strong>New</strong> on a card opens the create form for that journal type.</p><ul><li>Sale journal: <strong>New Invoice</strong>.</li><li>Purchase journal: <strong>New Bill</strong>.</li><li>Bank, cash and other liquidity journals: <strong>New Payment</strong>.</li><li>Miscellaneous journal: <strong>New Entry</strong>.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>In the sample data, the <strong>Customer Invoices</strong> card shows <strong>1 To Validate</strong> with 2,024.00 (the draft invoice for Lumber Wholesale Inc), <strong>1 Unpaid</strong> with 1,207.50 (INV/2026/1 for Azure Interiors) and <strong>1 To Pay</strong> with 1,207.50. The green bar sits in <strong>This Week</strong> because that invoice is not yet due.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the numbers as shortcuts. Click <strong>To Validate</strong> each morning to confirm drafts, and <strong>Late</strong> to chase customers.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li><li><a href="./../vendor-bills/create-bill.html">Create a vendor bill</a></li><li><a href="./journals.html">Journals</a></li><li><a href="./">Get started with finance</a></li></ul>',25))])}const b=o(l,[["render",h]]);export{v as __pageData,b as default};
